    T = 5

    def __init__(self, board, spin=turn_cw):
        self.spin = spin
        r, c = self.me_cells(board)
        self.r0, self.c0 = r % self.T, c % self.T
        self.rows, self.cols = (53 - self.r0) // self.T, (64 - self.c0) // self.T
        self.wall, self.box, self.tool = set(), {}, {}
        for i in range(self.rows):
            for j in range(self.cols):
                self.read_tile(board, i, j)

    @staticmethod
    def me_cells(board):
        for r in range(51):
            c = board[r].find("OOOOO")
            if c >= 0 and board[r + 1][c:c + 5] == "OOOOO" and board[r + 2][c:c + 5] == "bbbbb":
                return r, c

    def tile(self, board, i, j):
        r, c = self.r0 + self.T * i, self.c0 + self.T * j
        return [board[r + a][c:c + self.T] for a in range(self.T)]

    def read_tile(self, board, i, j):
        t = self.tile(board, i, j)
        if "".join(t).count("c") >= 10:
            self.wall.add((i, j))
            return
        mid = "".join(row[1:4] for row in t[1:4])
        edge = t[0] + t[4] + "".join(row[0] + row[4] for row in t[1:4])
        if set(edge) == {"B"} and set(mid) != {"B"}:
            self.box[(i, j)] = tuple(row[1:4] for row in t[1:4])
        elif "w" in mid and "W" in mid:
            self.tool[(i, j)] = "plus"

    def where(self, board):
        r, c = self.me_cells(board)
        return ((r - self.r0) // self.T, (c - self.c0) // self.T)

