    def key_of(board):
        return tuple(board[55 + 2 * a][3:9:2] for a in range(3))

    def start(self, board):
        return S(self.where(board), self.key_of(board))

    def free(self, p):
        return 0 <= p[0] < self.rows and 0 <= p[1] < self.cols and p not in self.wall

    def step(self, s, m):
        d = (s.pos[0] + DIRS[m][0], s.pos[1] + DIRS[m][1])
        if not self.free(d) or (d in self.box and self.box[d] != s.key):
            return None
        key = self.spin(s.key) if self.tool.get(d) == "plus" else s.key
        return replace(s, pos=d, key=key)

