    FULL = 42

    def __init__(self, board, spin=turn_cw, cost=1):
        self.cost = cost
        super().__init__(board, spin)
        self.rows = 11
        for j in range(self.cols):
            self.read_tile(board, 10, j)

    def read_tile(self, board, i, j):
        t = self.tile(board, i, j)
        if "".join(row[1:4] for row in t[1:4]) == "YYYYGYYYY":
            self.tool[(i, j)] = "ring"
            return
        super().read_tile(board, i, j)

    @staticmethod
    def bar_of(board):
        return board[61][13:55].count("Y")

    def start(self, board, used=frozenset()):
        return S2(self.where(board), self.key_of(board), self.bar_of(board), used)

    def step(self, s, m):
        n = super().step(s, m)
        if n is None:
            return None
        if self.tool.get(n.pos) == "ring" and n.pos not in s.used:
            return replace(n, bar=self.FULL, used=s.used | {n.pos})
        if s.bar - self.cost < 0:
            return None
        return replace(n, bar=s.bar - self.cost)

    def search(self, s0, goal):
        # keep, per (tile, key, rings used), only the visit with the most bar left
        best, q = {}, deque([(s0, "")])
        while q:
            s, path = q.popleft()
            if goal(s):
                return path
            for m in "1234":
                n = self.step(s, m)
                if n is None:
                    continue
                k = (n.pos, n.key, n.used)
                if best.get(k, -1) >= n.bar:
                    continue
                best[k] = n.bar
                q.append((n, path + m))
        return None

    def special(self, p):
        return p in self.tool or p in self.box

    def look(self, board):
        return (self.where(board), self.key_of(board), self.bar_of(board))

