        mid = "".join(row[1:4] for row in t[1:4])
        if mid[4] == "W" and len(set(mid)) >= 4:
            self.tool[(i, j)] = "colour"
            around = [t[1][1], t[1][2], t[1][3], t[2][3], t[3][3], t[3][2], t[3][1], t[2][1]]
            self.ring_order = "".join(dict.fromkeys(around))
            return
        super().read_tile(board, i, j)

    def find_pushers(self, board):
        push = {}
        for r in range(60):
            for j in range(self.cols):
                c = self.c0 + self.T * j
                if board[r][c:c + 5] == "wwwww":
                    i = (r - self.r0) // self.T
                    down = (r - self.r0) % self.T == self.T - 1
                    push[(i + 1, j) if down else (i - 1, j)] = (1, 0) if down else (-1, 0)
        for c in range(64):
            for i in range(self.rows):
                r = self.r0 + self.T * i
                if r + 5 <= 64 and all(board[r + a][c] == "w" for a in range(5)):
                    j = (c - self.c0) // self.T
                    right = (c - self.c0) % self.T == self.T - 1
                    push[(i, j + 1) if right else (i, j - 1)] = (0, 1) if right else (0, -1)
        return {p: d for p, d in push.items() if self.free(p)}

    def recolour(self, key):
        col = next(ch for row in key for ch in row if ch != "B")
        new = self.ring_order[(self.ring_order.index(col) + 1) % len(self.ring_order)]
        return tuple(row.replace(col, new) for row in key)

    def touch(self, p, s):
        kind = self.tool.get(p)
        if kind == "plus":
            return replace(s, key=self.spin(s.key))
        if kind == "colour":
            return replace(s, key=self.recolour(s.key))
        if kind == "ring" and p not in s.used:
            return replace(s, bar=self.FULL, used=s.used | {p})
        return s

    def step(self, s, m):
        d = (s.pos[0] + DIRS[m][0], s.pos[1] + DIRS[m][1])
        if not self.free(d) or (d in self.box and self.box[d] != s.key):
            return None
        if not (self.tool.get(d) == "ring" and d not in s.used):
            if s.bar - self.cost < 0:
                return None
            s = replace(s, bar=s.bar - self.cost)
        if d in self.push:
            di, dj = self.push[d]
            while self.free((d[0] + di, d[1] + dj)) and (d[0] + di, d[1] + dj) not in self.box:
                d = (d[0] + di, d[1] + dj)
        return self.touch(d, replace(s, pos=d))

    def special(self, p):
        return p in self.tool or p in self.box or p in self.push

