        Maze4.__init__(self, board, spin, cost, shape_next)
        for p in [p for p, k in self.tool.items() if k in self.tracks]:
            del self.tool[p]
        for tr in self.tracks.values():
            for p in tr:
                self.tool.setdefault(p, "track")
        self.period = math.lcm(*(len(v) for v in self.tracks.values()))

    def start(self, board, used=frozenset(), t=0, done=frozenset()):
        b = Maze4.start(self, board, used)
        return S6(b.pos, b.key, b.bar, b.used, t % self.period, done)

    def reshape(self, key):
        m = mask(key)
        for r in range(4):
            if m in self.shape_next:
                nm = self.shape_next[m]
                for _ in range((4 - r) % 4):
                    nm = turn_cw(nm)
                return paint(nm, next(ch for row in key for ch in row if ch != "B"))
            m = turn_cw(m)
        return self.UNKNOWN if self.probe else None

    def touch(self, p, s):
        for kind, tr in self.tracks.items():
            if p == tr[s.t % len(tr)]:
                if kind == "plus":
                    return replace(s, key=self.spin(s.key))
                if kind == "colour":
                    return replace(s, key=self.recolour(s.key))
                k = self.reshape(s.key)
                return None if k is None else replace(s, key=k)
        return Maze3.touch(self, p, s)

    def step(self, s, m):
        if s.key == self.UNKNOWN:
            return None
        s = replace(s, t=(s.t + 1) % self.period)
        d = (s.pos[0] + DIRS[m][0], s.pos[1] + DIRS[m][1])
        if not self.free(d) or (d in self.box and d not in s.done and self.box[d] != s.key):
            return None
        if not (self.tool.get(d) == "ring" and d not in s.used):
            if s.bar - self.cost < 0:
